package cn.huankan.event;
import java.util.*;import java.nio.charset.StandardCharsets;import java.math.BigDecimal;
import cn.huankan.collector.SdmxCsv;import cn.huankan.evidence.EvidenceService;
import com.fasterxml.jackson.databind.ObjectMapper;import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class AtomicFactService {
 private final JdbcTemplate db;private final ObjectMapper json;
 public AtomicFactService(JdbcTemplate db,ObjectMapper json){this.db=db;this.json=json;}
 private String encode(Object x){try{return json.writeValueAsString(x);}catch(Exception e){throw new IllegalArgumentException("事实字段无法编码");}}
 @Transactional public Object extract(int limit){if(limit<1||limit>500)throw new IllegalArgumentException("抽取批次应为1至500");db.execute("SELECT pg_advisory_xact_lock(742031)");int macro=0,publication=0;
  var observations=db.queryForList("SELECT m.*,r.raw_content,r.raw_content_hash,r.source_url,r.published_at,r.collected_at FROM macro_observation m JOIN raw_evidence r ON r.id=m.evidence_id WHERE NOT EXISTS(SELECT 1 FROM fact_candidate f WHERE f.observation_id=m.evidence_id) ORDER BY m.observation_date,m.series_id LIMIT ?",limit);
  for(var m:observations){byte[] bytes=(byte[])m.get("raw_content");if(!EvidenceService.hash(bytes).equals(m.get("raw_content_hash")))throw new IllegalArgumentException("宏观证据哈希不一致");String series=m.get("series_id").toString(),date=m.get("observation_date").toString();var matches=SdmxCsv.parse(bytes,series).stream().filter(o->o.date().toString().equals(date)).toList();if(matches.size()!=1)throw new IllegalArgumentException("宏观观测没有唯一原始行");var o=matches.getFirst();BigDecimal value=(BigDecimal)m.get("value");if(value==null?o.value()!=null:o.value()==null||value.compareTo(o.value())!=0)throw new IllegalArgumentException("观测值与实际响应不一致");
   String raw=new String(bytes,StandardCharsets.UTF_8);String line=raw.lines().filter(x->x.startsWith(series+",")&&x.contains(","+date+",")).findFirst().orElseThrow();var fields=new LinkedHashMap<String,Object>();fields.put("indicator_id",series);fields.put("observation_period",date);fields.put("actual_value",value);fields.put("unit",o.metadata().get("UNIT"));fields.put("frequency",o.metadata().get("FREQ"));fields.put("currency",o.metadata().get("CURRENCY"));fields.put("currency_denominator",o.metadata().get("CURRENCY_DENOM"));fields.put("unit_multiplier",o.metadata().get("UNIT_MULT"));fields.put("source","ECB_DATA");fields.put("source_url",m.get("source_url"));fields.put("collected_at",m.get("collected_at"));fields.put("source_published_at",m.get("published_at"));fields.put("revision",m.get("version"));fields.put("interpretation","官方观测字段一致，参考汇率不等同成交行情；原始发布时间未知时保持为空");
   add("macro:"+series+":"+date,((Number)m.get("version")).intValue(),"MACRO_OBSERVATION",null,(UUID)m.get("evidence_id"),fields,"SDMX字段逐列校验-1.0","FIELD_MATCHED",(UUID)m.get("evidence_id"),line,"CSV:KEY="+series+";TIME_PERIOD="+date,m.get("published_at"));macro++;
  }
  var events=db.queryForList("SELECT e.*,r.raw_content,r.raw_content_hash,r.source_url,r.published_at,r.revision,s.name publisher FROM financial_event e JOIN raw_evidence r ON r.id=e.evidence_id JOIN source_registry s ON s.id=e.source_id WHERE e.source_id IN('FED','ECB','NBS') AND NOT EXISTS(SELECT 1 FROM fact_evidence p JOIN fact_candidate f ON f.id=p.fact_id WHERE f.event_id=e.id AND p.evidence_id=e.evidence_id) ORDER BY r.ingested_at LIMIT ?",limit);
  for(var e:events){byte[] bytes=(byte[])e.get("raw_content");if(!EvidenceService.hash(bytes).equals(e.get("raw_content_hash")))throw new IllegalArgumentException("公告证据完整性失败");String full=new String(bytes,StandardCharsets.UTF_8),title=e.get("original_title").toString(),escaped=title.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;");String quote=full.contains(title)?title:full.contains(escaped)?escaped:null;if(quote==null||quote.length()<5)continue;
   var fields=new LinkedHashMap<String,Object>();fields.put("publisher",e.get("publisher"));fields.put("original_title",title);fields.put("document_published_at",e.get("published_at"));fields.put("source_url",e.get("source_url"));fields.put("scope","确认官方已发布此标题，未独立核实标题内现实经济结论");int version=((Number)e.get("revision")).intValue();add("publication:"+e.get("id"),version,version>1?"DOCUMENT_REVISION":"OFFICIAL_PUBLICATION",(UUID)e.get("id"),null,fields,"原始标题逐字定位-1.0","SOURCE_CHECKED",(UUID)e.get("evidence_id"),quote,"UTF8代码点:"+full.codePointCount(0,full.indexOf(quote)),e.get("published_at"));publication++;
  }
  int legal=0;for(var l:db.queryForList("SELECT g.*,r.raw_content,r.raw_content_hash,r.revision FROM gleif_legal_record g JOIN raw_evidence r ON r.id=g.evidence_id WHERE NOT EXISTS(SELECT 1 FROM fact_evidence p JOIN fact_candidate f ON f.id=p.fact_id WHERE p.evidence_id=g.evidence_id AND f.fact_type='LEGAL_IDENTITY_ATTRIBUTE') ORDER BY g.lei LIMIT ?",limit)){byte[] bytes=(byte[])l.get("raw_content");if(!EvidenceService.hash(bytes).equals(l.get("raw_content_hash")))throw new IllegalArgumentException("法人证据完整性失败");var fields=new LinkedHashMap<String,Object>();fields.put("entity_id",l.get("entity_id"));fields.put("lei",l.get("lei"));fields.put("legal_name",l.get("legal_name"));fields.put("jurisdiction",l.get("jurisdiction"));fields.put("entity_status",l.get("entity_status"));fields.put("registration_status",l.get("registration_status"));fields.put("registration_last_update",l.get("last_update"));fields.put("scope","GLEIF登记身份字段；登记更新时间不等于首次公开时间；不能推断供应链或证券表现");add("legal:"+l.get("lei"),((Number)l.get("revision")).intValue(),"LEGAL_IDENTITY_ATTRIBUTE",null,null,fields,"精确LEI与官方JSON字段核对-1.0","SOURCE_CHECKED",(UUID)l.get("evidence_id"),new String(bytes,StandardCharsets.UTF_8),"JSON:attributes/entity;attributes/registration",null);legal++;}
  return Map.of("legal_inserted",legal,"macro_inserted",macro,"publication_inserted",publication,"independent_supported",0);
 }
 private void add(String key,int version,String type,UUID event,UUID observation,Object fields,String method,String status,UUID evidence,String quote,String locator,Object available){UUID id=UUID.randomUUID();db.update("INSERT INTO fact_candidate(id,fact_key,version,fact_type,event_id,observation_id,fields,extraction_method,verification_status,available_at) VALUES(?,?,?,?,?,?,?::jsonb,?,?,?)",id,key,version,type,event,observation,encode(fields),method,status,available);db.update("INSERT INTO fact_evidence VALUES(?,?,?,?)",id,evidence,quote,locator);var old=db.queryForList("SELECT id FROM fact_candidate WHERE fact_key=? AND version<? ORDER BY version DESC LIMIT 1",key,version);if(!old.isEmpty())db.update("INSERT INTO fact_revision VALUES(?,?,?)",id,old.getFirst().get("id"),"官方资料的新版本；旧值与旧证据保留");}
 public Object query(int page,String type){if(page<0||page>100000||type==null||type.length()>80)throw new IllegalArgumentException("事实查询无效");var rows=db.queryForList("SELECT f.*,COALESCE((SELECT decision FROM fact_review v WHERE v.fact_id=f.id ORDER BY created_at DESC,id DESC LIMIT 1),f.verification_status) effective_status,p.evidence_id,p.excerpt,p.source_locator,r.source_url,r.raw_content_hash,r.collected_at FROM fact_candidate f JOIN fact_evidence p ON p.fact_id=f.id JOIN raw_evidence r ON r.id=p.evidence_id WHERE (?='' OR f.fact_type=?) ORDER BY f.created_at DESC,f.id LIMIT 50 OFFSET ?",type,type,page*50);for(var row:rows)try{row.put("fields",json.readValue(row.get("fields").toString(),Map.class));}catch(Exception e){throw new IllegalArgumentException("事实结构化字段无法读取");}return rows;}
 public record Review(String decision,String actor,String reason,UUID evidenceId,String excerpt){}
 @Transactional public void review(UUID id,Review q){if(q.decision()==null||!Set.of("SOURCE_CHECKED","FIELD_MATCHED","INDEPENDENT_SUPPORTED","CONFLICT","INSUFFICIENT","REJECTED").contains(q.decision())||q.actor()==null||q.actor().isBlank()||q.actor().length()>200||q.reason()==null||q.reason().length()<10||q.reason().length()>4000||q.evidenceId()==null||q.excerpt()==null||q.excerpt().length()<5||q.excerpt().length()>4000)throw new IllegalArgumentException("事实审核依据、证据与责任人不足");db.update("INSERT INTO fact_review(fact_id,decision,actor,reason,evidence_id,excerpt) VALUES(?,?,?,?,?,?)",id,q.decision(),q.actor(),q.reason(),q.evidenceId(),q.excerpt());}
 public Object history(UUID id){return db.queryForList("SELECT * FROM fact_review WHERE fact_id=? ORDER BY created_at DESC,id DESC LIMIT 100",id);}
}
